import { redactSensitive } from '@tactia/shared';

export type FormatEpisodeTextInput = {
  actionType: string;
  origin: string;
  outcome: string;
  reason?: string | null;
  input?: unknown;
};

function asRecord(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return value as Record<string, unknown>;
}

function asText(value: unknown): string {
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : '—';
}

/**
 * Deterministic pt-BR episode text. Never generated by the LLM.
 * Does not include e-mail bodies (PII / injection).
 */
export function formatEpisodeText(input: FormatEpisodeTextInput): string {
  const lines = [
    `Proposta ${input.actionType} (${input.origin}): ${input.outcome}.`,
    `Motivo da proposta: ${input.reason?.trim() || '—'}.`,
  ];
  const payload = asRecord(input.input);
  if (input.actionType === 'send_email') {
    lines.push(`Destinatário: ${asText(payload.to)}; assunto: ${asText(payload.subject)}`);
  }
  if (input.actionType === 'create_task') {
    lines.push(`Tarefa: ${asText(payload.title)}`);
  }
  return redactSensitive(lines.join('\n'));
}

export function entityFromActionInput(input: unknown): {
  entityType: string | null;
  entityId: string | null;
} {
  const payload = asRecord(input);
  if (typeof payload.customerId === 'string') {
    return { entityType: 'customer', entityId: payload.customerId };
  }
  if (typeof payload.sellerId === 'string') {
    return { entityType: 'seller', entityId: payload.sellerId };
  }
  if (typeof payload.leadId === 'string') {
    return { entityType: 'lead', entityId: payload.leadId };
  }
  return { entityType: null, entityId: null };
}
